$(document).ready(function() {
    $('.showMobileMenu--js').on('click', function(event) {
        event.preventDefault();
        showMobileMenu();
    });

});

$(document).on('click.myEvent', function(e) {
    if ($(e.target).closest('.mobile-header-show').length == 0 &&
        $(e.target).closest('.showMobileMenu--js').length == 0) {
        hideMobileMenu();
    }
});

function showMobileMenu() {
    $('.mobile-header-show').animate({
        left: 0,
    }, 300);
    $('.mobile-header-show__shadow').fadeIn(300);
    $('html, body').css('overflow', 'hidden');
}

function hideMobileMenu() {
    $('.mobile-header-show').animate({
        left: '-23rem',
    }, 300);
    $('.mobile-header-show__shadow').fadeOut(300);
    $('html, body').removeAttr('style');
}

$(document).ready(function() {
    $('.lang-switch_desktop').click(function() {
        $(this).toggleClass('active');
    });
});

$(document).on('click.myEvent', function(e) {
    if ($(e.target).closest('.lang-switch_desktop').length == 0) {
        $('.lang-switch_desktop').removeClass('active');
    }
});
$(document).ready(function() {
    $('.toogleSubMenu--js').click(function() {
        $(this).toggleClass('active');

        $('.mobile-sub-menu').slideToggle(300);
    });



    $('.form#request-basket').on('submit', function (e) {
        e.preventDefault();

        var data = {
            MAIL_FROM: $(this).find('[name="MAIL_FROM"]').val(),
            PHONE: $(this).find('[name="PHONE"]').val(),
            REGION: $(this).find('[name="region"]').val(),
            COMMENT: $(this).find('[name="COMMENT"]').val(),
            EMAIL: $(this).find('[name="EMAIL"]').val(),
        };

        //choose delivery
        let typeOfDelivery = $(this).find('[name="DELIVERY"]').val();
        if (typeOfDelivery === null){
            alert('Выберите способ доставки');
            return null;
        }else if (typeOfDelivery === 'novaP') {
            data.DELIVERY = 'Доставка новой почтой';
            data.ADDRESS = $(this).find('[name="CITY"]').val() + ' ' +
                $(this).find('[name="BRANCH"]').val();
        }else if(typeOfDelivery === 'courier'){
            data.DELIVERY = 'Адресная доставка';
            data.ADDRESS = $(this).find('[name="CITY"]').val() + ' ' +
                $(this).find('[name="NUMBER"]').val() + ' ' +
                $(this).find('[name="STREET"]').val();
        }else if(typeOfDelivery === 'pickup'){
            data.DELIVERY = 'Самовывоз';
            data.ADDRESS = 'Бориспіль вул. Вишнева 16';
        }


        $.ajax({
            url: '/local/templates/kdteam/includes/product/buy-parts.php',
            type: 'POST',
            dataType: 'json',
            data: data,
            success: function (data) {
                googleSendEvent('submit','form_parts',window.location.href);
                console.log('success');
                console.log(data)
                if (data.success) {
                    $('.header_basket__count').text(0);
                    showModalSuccessBasket();

                } else {
                    console.log('ошибка');
                }
            },
            complete: function () {
                console.log('complete')
                $(this).find("input[type=text],input[type=tel],input[type=hidden], select, textarea").val("");
                $('#request-basket')[0].reset();
            }
        })
    });

    $("a.add2basket").on("click", function (e) {
        console.log('click add2basket')
        e.preventDefault();
        var t = $(this).data("id"),
            n = $("html").attr("lang");
        $.ajax({
            url: "/local/templates/kdteam/includes/ajax-basket.php",
            type: "POST",
            dataType: "html",
            data: { id: t },
            success: function (htmlString) {
                console.log(htmlString)
                document.querySelector('.header_basket__inner').remove();
                console.log(document.querySelector('header .header__wrap'))
                document.querySelector('.header .header__wrap').insertAdjacentHTML('beforeend', htmlString)
                // const cartBody = document.querySelector('.cart-modal-body'); // перевіримо, чи є цей блок
                // if (cartBody) {
                //     cartBody.innerHTML = data;
                // }

                "ua" === n ? $('#addToBasket[data-id="' + t + '"]').html("У кошику") : $('#addToBasket[data-id="' + t + '"]').html("В корзине");
            },
        });
    });

    $(document).on('click', '.basket__item_remove', function (e) {
        e.preventDefault();

        var productId = $(this).parents('.basket__item').data('id');
        var lang = $('html').attr('lang');

        $.ajax({
            url: '/local/templates/kdteam/includes/ajax-basket.php',
            type: 'POST',
            dataType: 'json',
            data: {
                id: productId
            },
            success: function (data) {
                if(data.success) {
                    $('input[NAME="CART"]').val(data.basketData);

                    if(data.removed === true) {
                        $('.header_basket__count').html(Number(data.basketCount));
                        if(data.basketCount < 1) {
                            $('.basket__empty').removeClass('hidden');
                            $('.show-modal-basket').addClass('hidden');
                        }

                        $('.basket__item[data-id="'+productId+'"]').remove();

                        if(lang === 'ua') {
                            $('#addToBasket[data-id="'+productId+'"]').html('У кошик');
                        } else {
                            $('#addToBasket[data-id="'+productId+'"]').html('В корзину');
                        }

                        $(this).parents('.basket__item').remove();
                    }
                }
            }
        });
    });
    $('.section_seo__read-more').click(function() {
        var tytop = window.scrollY;
        $('html, body').animate({scrollTop: tytop}, 300);
        $(this).hide();
        $('.section_seo__preview-text').css('height', 'auto');

    });



    $('input[type=\'tel\']').mask('+38 (000) 000-00-00');


    $('.fancybox').fancybox();
    $(".show-modal-basket").fancybox({
        'href': '#modal-basket',
        'titleShow': false,
        'transitionIn': 'elastic',
        'transitionOut': 'elastic',
        'wrapCSS' : 'fixHeight'

    });
});

function showModalSuccess() {
    $.fancybox.close();
    $.fancybox.open({
        'href': '#modal-success',
        'titleShow': false,
        'transitionIn': 'elastic',
        'transitionOut': 'elastic',
    });

}

function showModalSuccessBasket() {
    $.fancybox.close();
    $.fancybox.open({
        'href': '#modal-success-basket',
        'titleShow': false,
        'transitionIn': 'elastic',
        'transitionOut': 'elastic',
        'afterClose' : function() {
            window.location = '/'
        }
    });

}

function clearCart() {
    $.ajax({
        url: '/local/templates/kdteam/includes/cart-clear.php',
        type: 'POST',
        dataType: 'json',
        success: function (data) {
            if (data.success === false) {
                console.log('cart clearing error');
            } else {
                $('.show-modal-basket').addClass('hidden');
                var lang = $('html').attr('lang');

                var $elements = document.getElementsByClassName('add-to-basket');

                $.each($elements, function (index, element) {
                    if (lang === 'ua') {
                        $(element).html('У кошик');
                    } else {
                        $(element).html('В корзину');
                    }
                });
            }
        }
    });
}

//select delivery
document.addEventListener('DOMContentLoaded', () => {
    const selectDelivery = document.querySelector('#DELIVERY');
    const input = document.querySelector('.form__delivery-input');
    const inputLabel = document.querySelector('.select-label');
    const courierForm = document.createElement('div');
    const novaPoshtaForm = document.createElement('div');
    const pickupForm = document.createElement('div');
    var lang = $('html').attr('lang');
    if(!selectDelivery || !input) {
        return;
    }

    courierForm.classList.add('courier-form');
    novaPoshtaForm.classList.add('nova-poshta-form');

    courierForm.innerHTML = `
                                <div>
                                    <div class="form-group form-group_text delivery-input">
                                        <input class="form-control" type="text" name="CITY" id="CITY" autocomplete="off"
                                               placeholder=" " required>
                                        <label for="CITY"
                                               class="form-label">${multiLang('Введіть місто', 'Введите город')}
                                        </label>
                                    </div>
                                </div>
                                <div>
                                    <div class="form-group form-group_text delivery-input">
                                        <input class="form-control" type="text" name="STREET" id="STREET" autocomplete="off"
                                               placeholder=" " required>
                                        <label for="STREET"
                                               class="form-label">${multiLang('Введіть вулицю', 'Введите улицу')}
                                        </label>
                                    </div>
                                </div>
                                <div>
                                    <div class="form-group form-group_text delivery-input">
                                        <input class="form-control" type="text" name="NUMBER" id="NUMBER" autocomplete="off"
                                               placeholder=" " required>
                                        <label for="NUMBER"
                                               class="form-label">${multiLang('Введіть номер будинку і квартири', 'Введите номер дома и квартиры')}
                                        </label>
                                    </div>
                                </div>
    `;

    novaPoshtaForm.innerHTML = `
         <div>
             <div class="form-group form-group_text delivery-input">
                <input class="form-control" type="text" name="CITY" id="CITY" autocomplete="off"
                       placeholder=" " required>
                <label for="CITY"
                    class="form-label">${multiLang('Введіть місто', 'Введите город')}
                </label>
             </div>
         </div>
         <div>
            <div class="form-group form-group_text delivery-input">
                 <input class="form-control" type="text" name="BRANCH" id="BRANCH" autocomplete="off"
                       placeholder=" " required>
                 <label for="BRANCH"
                       class="form-label">${multiLang('Введіть номер НП', 'Введите номер НП')}
                 </label>
            </div>
         </div>
    `;

    pickupForm.innerHTML = `
    <div class="pt-2">${multiLang('Бориспіль вул. Вишнева 16', 'Борисполь ул. Вишневая 16')}</div>
    `

    function multiLang(ua, rus) {
        if(lang === 'ua') {
            return ua
        }else{
            return rus
        }
    }

    function deliveryType() {
        if (selectDelivery.value == 'courier') {
            selectDelivery.classList.add('active');
            inputLabel.classList.add('active');
            input.appendChild(novaPoshtaForm);
            input.removeChild(novaPoshtaForm);
            input.removeChild(pickupForm);
            input.appendChild(courierForm);


        }else if (selectDelivery.value == 'novaP') {
            selectDelivery.classList.add('active');
            inputLabel.classList.add('active');
            input.appendChild(courierForm);
            input.removeChild(courierForm);
            input.removeChild(pickupForm);
            input.appendChild(novaPoshtaForm);
        } else if (selectDelivery.value == 'pickup') {
            selectDelivery.classList.add('active');
            inputLabel.classList.add('active');
            input.appendChild(pickupForm);
            input.removeChild(courierForm);
            input.removeChild(novaPoshtaForm);
        }
    }
    selectDelivery.addEventListener('change', () => {
        deliveryType();
        console.log(selectDelivery.value);
    })
})


